-- ㄱ. CROSS JOIN
SELECT COUNT(*) FROM TAB1, TAB2;

-- ㄴ. INNER JOIN
SELECT COUNT(*)
FROM TAB1 A INNER JOIN TAB2 B
  ON A.ID = B.ID;

-- ㄷ. FULL OUTER JOIN
SELECT COUNT(*)
FROM TAB1 A FULL OUTER JOIN TAB2 B
  ON A.ID = B.ID;

